SELECT t.project_id AS projectId, t.applicable_month AS applicableMonth, c.company_abbreviation AS companyAbbreviation, d.department_abbreviation AS departmentAbbreviation, d.principal_name AS principalName, p.project_name_abbreviation AS projectNameAbbreviation, t.trading_status AS tradingStatus, t.total_sales_amount AS totalSalesAmount, t.total_amount_raised AS totalAmountRaised FROM basic_v2_trading_management t JOIN basic_v2_project_manage p ON t.project_id = p.project_id JOIN basic_v2_company_management c ON t.sales_company_id = c.company_id JOIN basic_v2_department_management d ON t.department_id = d.department_id WHERE t.project_id IN
#{item}
AND applicable_month BETWEEN #{startDate} AND #{endDate} AND t.active_flg = 1

SELECT SUM(total_labor_expenses) FROM basic_v2_labor_management WHERE staff_id IN
#{item}
AND active_flg = 1
